 aistorage:{name:'Local flash and BOSS boot',what:'Local SSDs store software and data; separate M.2 boot devices can reserve front bays for workload storage.',design:'XE9680 lists 8-SFF or 16-E3.S configurations. Gaudi 3 is restricted to the 8-SFF NVMe layout in the linked specification.',src:'xe9680spec'},
